/**
 * Sign release builds with DASH's Play upload key — when, and only when, the
 * key is supplied through the environment.
 *
 * The native android/ project is generated by `expo prebuild` and never
 * committed, so the signing configuration has to be written into it at
 * generation time. This plugin adds a `dashUpload` signing config to
 * app/build.gradle that reads the keystore path and passwords from
 * environment variables at *build* time:
 *
 *   DASH_UPLOAD_STORE_FILE       absolute path to the upload keystore (.jks)
 *   DASH_UPLOAD_STORE_PASSWORD   keystore password
 *   DASH_UPLOAD_KEY_ALIAS        key alias inside the keystore
 *   DASH_UPLOAD_KEY_PASSWORD     key password
 *
 * Nothing secret is ever written into a file: build.gradle holds only the
 * variable names. If any variable is missing, the release build keeps the
 * template's debug signing — which Play refuses — so an unsigned-for-Play
 * bundle can never be mistaken for an uploadable one.
 *
 * The keystore itself lives outside the repository (see
 * docs/release/SIGNING.md). It must never be committed.
 */

const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// dash-release-signing';

const SIGNING_CONFIG = `
        ${MARKER}
        dashUpload {
            def storeFilePath = System.getenv('DASH_UPLOAD_STORE_FILE')
            if (storeFilePath) {
                storeFile file(storeFilePath)
                storePassword System.getenv('DASH_UPLOAD_STORE_PASSWORD')
                keyAlias System.getenv('DASH_UPLOAD_KEY_ALIAS')
                keyPassword System.getenv('DASH_UPLOAD_KEY_PASSWORD')
            }
        }`;

const RELEASE_SELECTION = `
            ${MARKER}
            if (System.getenv('DASH_UPLOAD_STORE_FILE') && System.getenv('DASH_UPLOAD_STORE_PASSWORD') && System.getenv('DASH_UPLOAD_KEY_ALIAS') && System.getenv('DASH_UPLOAD_KEY_PASSWORD')) {
                signingConfig signingConfigs.dashUpload
            }`;

function addSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  const withConfig = gradle.replace(/(signingConfigs\s*\{)/, `$1${SIGNING_CONFIG}`);
  if (withConfig === gradle) throw new Error('withReleaseSigning: signingConfigs block not found in app/build.gradle');

  // The release build type's own `signingConfig signingConfigs.debug` line is
  // left in place; this one, placed after it, overrides it when the key is set.
  const withRelease = withConfig.replace(/(buildTypes\s*\{[\s\S]*?release\s*\{[^}]*?signingConfig\s+signingConfigs\.debug)/, `$1${RELEASE_SELECTION}`);
  if (withRelease === withConfig) throw new Error('withReleaseSigning: release build type not found in app/build.gradle');
  return withRelease;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') throw new Error('withReleaseSigning: expected a Groovy build.gradle');
    mod.modResults.contents = addSigning(mod.modResults.contents);
    return mod;
  });
};

module.exports.addSigning = addSigning;
